import{_ as t,o as i,c as a,ag as r}from"./chunks/framework.DXGyWiRo.js";const p=JSON.parse('{"title":"Security Model","description":"","frontmatter":{},"headers":[],"relativePath":"security-model.md","filePath":"security-model.md","lastUpdated":1777882948000}'),o={name:"security-model.md"};function n(s,e,l,d,c,u){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="security-model" tabindex="-1">Security Model <a class="header-anchor" href="#security-model" aria-label="Permalink to &quot;Security Model&quot;">​</a></h1><h2 id="authentication-and-sessions" tabindex="-1">Authentication and Sessions <a class="header-anchor" href="#authentication-and-sessions" aria-label="Permalink to &quot;Authentication and Sessions&quot;">​</a></h2><p>RustChat uses JWT tokens for authentication:</p><ul><li>Tokens are signed with <code>RUSTCHAT_JWT_SECRET</code> (HS256)</li><li>Token expiry is configurable (default 24 hours)</li><li>Passwords are hashed with Argon2id</li><li>OAuth/SAML SSO is supported via configurable providers</li></ul><h3 id="websocket-authentication" tabindex="-1">WebSocket Authentication <a class="header-anchor" href="#websocket-authentication" aria-label="Permalink to &quot;WebSocket Authentication&quot;">​</a></h3><p>WebSocket connections accept tokens via:</p><ul><li><code>Authorization: Bearer &lt;token&gt;</code> header (preferred)</li><li><code>Sec-WebSocket-Protocol</code> header fallback</li></ul><p>Query-string token transport is disabled by default in production.</p><h3 id="session-storage" tabindex="-1">Session Storage <a class="header-anchor" href="#session-storage" aria-label="Permalink to &quot;Session Storage&quot;">​</a></h3><p>Active sessions and rate-limit state are stored in Redis. PostgreSQL is the source of truth for users, teams, and permissions.</p><h2 id="authorization" tabindex="-1">Authorization <a class="header-anchor" href="#authorization" aria-label="Permalink to &quot;Authorization&quot;">​</a></h2><p>Role-based access control (RBAC) is implemented:</p><ul><li><code>system_admin</code> — Full platform access</li><li><code>team_admin</code> — Team-level administration</li><li><code>channel_admin</code> — Channel-level administration</li><li>Standard user roles</li></ul><p>Permissions are checked at the API handler layer before reaching services.</p><h2 id="dependency-security-process" tabindex="-1">Dependency Security Process <a class="header-anchor" href="#dependency-security-process" aria-label="Permalink to &quot;Dependency Security Process&quot;">​</a></h2><ul><li><strong>Dependabot</strong> monitors Cargo, npm, GitHub Actions, and Docker dependencies</li><li><strong>cargo audit</strong> runs in CI on every push and weekly to detect known vulnerable crates</li><li><strong>npm audit</strong> runs in CI for frontend dependencies</li><li><strong>CodeQL</strong> static analysis runs for Rust and JavaScript</li><li>Security-related dependency updates are treated as high priority</li></ul><h2 id="vulnerability-reporting" tabindex="-1">Vulnerability Reporting <a class="header-anchor" href="#vulnerability-reporting" aria-label="Permalink to &quot;Vulnerability Reporting&quot;">​</a></h2><p><strong>Do not open public issues for security vulnerabilities.</strong></p><p>Report privately via GitHub Security Advisories or contact maintainers directly. See <code>SECURITY.md</code> for full instructions.</p><h2 id="supported-versions" tabindex="-1">Supported Versions <a class="header-anchor" href="#supported-versions" aria-label="Permalink to &quot;Supported Versions&quot;">​</a></h2><p>RustChat is currently pre-1.0 and under active development.</p><table tabindex="0"><thead><tr><th>Version</th><th>Supported</th></tr></thead><tbody><tr><td><code>main</code> (current development)</td><td>Yes</td></tr><tr><td>Latest tagged release</td><td>Yes</td></tr><tr><td>Older releases</td><td>No</td></tr></tbody></table><p>Before 1.0, minor version bumps may include breaking changes. Review <code>CHANGELOG.md</code> before upgrading.</p><h2 id="nightly-stability-disclaimer" tabindex="-1">Nightly Stability Disclaimer <a class="header-anchor" href="#nightly-stability-disclaimer" aria-label="Permalink to &quot;Nightly Stability Disclaimer&quot;">​</a></h2><p>Nightly container images are built automatically from <code>main</code>. They are not guaranteed to be stable and should be used for testing only.</p><h2 id="production-hardening-checklist" tabindex="-1">Production Hardening Checklist <a class="header-anchor" href="#production-hardening-checklist" aria-label="Permalink to &quot;Production Hardening Checklist&quot;">​</a></h2><ul><li>[ ] Set <code>RUSTCHAT_ENVIRONMENT=production</code></li><li>[ ] Generate strong secrets (≥32 chars, high entropy, unique per secret)</li><li>[ ] Set explicit <code>RUSTCHAT_CORS_ALLOWED_ORIGINS</code> (no wildcards)</li><li>[ ] Use <code>RUSTCHAT_SECURITY_OAUTH_TOKEN_DELIVERY=cookie</code></li><li>[ ] Disable query-string WebSocket tokens: <code>RUSTCHAT_SECURITY_WS_ALLOW_QUERY_TOKEN=false</code></li><li>[ ] Enable rate limiting (on by default)</li><li>[ ] Terminate TLS at a reverse proxy</li><li>[ ] Forward <code>X-Forwarded-For</code> for accurate rate limiting</li><li>[ ] Configure security headers (HSTS, X-Frame-Options, X-Content-Type-Options)</li></ul><p>See <a href="./security-deployment-guide">Security Deployment Guide</a> for a complete hardening guide.</p>',28)])])}const m=t(o,[["render",n]]);export{p as __pageData,m as default};
